parameters.text:
=Tengo estos ingredientes disponibles: {{ JSON.stringify($json.body.ingredients) }}. Sugiere exactamente 3 platos que se puedan preparar con ellos. Para cada plato incluye el nombre y una breve idea de receta. Responde en español en formato JSON estricto.

Formato de respuesta:
{
  "dishes": [
    {"name": "Nombre del plato 1", "idea": "Breve descripción de la preparación"},
    {"name": "Nombre del plato 2", "idea": "Breve descripción de la preparación"},
    {"name": "Nombre del plato 3", "idea": "Breve descripción de la preparación"}
  ]
}

parameters.jsonSchemaExample:
{
  "dishes": [
    {
      "name": "Tortilla de papas",
      "idea": "Batir los huevos, freír las papas y cuajar en sartén."
    },
    {
      "name": "Sopa de verduras",
      "idea": "Sofreír las verduras y hervir con caldo hasta que estén tiernas."
    },
    {
      "name": "Ensalada templada",
      "idea": "Saltear los ingredientes y servir sobre hojas frescas."
    }
  ]
}
